const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'mutualAid') throw new Error('unsupported_resource');
const recordId = text(fields.request_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const unitId = text(fields.unit_id);
if (!unitId) throw new Error('unit_id_required');
const acceptedRaw = fields.accepted_quantity;
const accepted = typeof acceptedRaw === 'number' ? acceptedRaw : typeof acceptedRaw === 'string' && acceptedRaw.trim() ? Number(acceptedRaw) : null;
if (accepted === null || !Number.isFinite(accepted) || accepted <= 0) throw new Error('invalid_accepted_quantity');
let etaMinutes = null;
if (fields.eta_minutes !== undefined && fields.eta_minutes !== null && String(fields.eta_minutes).trim() !== '') {
  const num = Number(fields.eta_minutes);
  if (!Number.isFinite(num) || num < 0) throw new Error('eta_minutes_invalid');
  etaMinutes = num;
}
const allowed = new Set(['request_id', 'unit_id', 'accepted_quantity', 'eta_minutes']);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const audit = {
  product, resource, operation: 'mutualAid.accept', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};
return { recordId, encodedId: encodeURIComponent(recordId), unitId, encodedUnitId: encodeURIComponent(unitId), accepted, etaMinutes, audit };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('mutual_aid_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const request = { ...current.data, id: String(current.data.id || current.id) };
const status = String(request.status);
if (!['open', 'partially_filled'].includes(status)) throw new Error('request_not_open');
const quantity = typeof request.quantity === 'number' && Number.isFinite(request.quantity) ? request.quantity : Number(request.quantity) || 0;
const filled = typeof request.filled_quantity === 'number' && Number.isFinite(request.filled_quantity) ? request.filled_quantity : Number(request.filled_quantity) || 0;
const remaining = Math.max(quantity - filled, 0);
if (state.accepted > remaining) throw new Error('quantity_exceeds_request');
return { ...state, request, version: current.version, quantity, filled, remaining };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('resource_unit_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const unit = { ...current.data, id: String(current.data.id || current.id) };
const unitStatus = String(unit.status || '');
if (['offline', 'maintenance'].includes(unitStatus)) throw new Error('resource_unit_unavailable');
const rawAvailable = unit.available_quantity !== undefined && unit.available_quantity !== null ? unit.available_quantity
  : unit.capacity !== undefined && unit.capacity !== null ? unit.capacity
  : unit.quantity !== undefined && unit.quantity !== null ? unit.quantity : null;
const available = typeof rawAvailable === 'number' && Number.isFinite(rawAvailable) ? rawAvailable
  : typeof rawAvailable === 'string' && rawAvailable.trim() && Number.isFinite(Number(rawAvailable)) ? Number(rawAvailable) : null;
if (available === null) throw new Error('capacity_metadata_required');
if (state.accepted > available) throw new Error('insufficient_capacity');
const nextFilled = state.filled + state.accepted;
const nextStatus = nextFilled >= state.quantity ? 'filled' : 'partially_filled';
const history = Array.isArray(state.request.history) ? [...state.request.history] : [];
history.push({ action: 'accept', unit_id: state.unitId, accepted_quantity: state.accepted, eta_minutes: state.etaMinutes, at: $now, by: state.audit.submittedBy });
const unitNext = { ...unit, available_quantity: Math.max(available - state.accepted, 0), updated_at: $now };
const requestNext = { ...state.request, filled_quantity: nextFilled, status: nextStatus, updated_at: $now, history };
return { ...state, unit, unitVersion: current.version, unitBody: { data: unitNext, ifVersion: current.version }, requestBody: { data: requestNext, ifVersion: state.version } };

